import React, { useMemo, useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  Search,
  Database,
  Building2,
  FileText,
  Tag,
  CheckCircle2,
  AlertCircle,
  ArrowRight,
  Sparkles,
  X
} from 'lucide-react';

export const AIMatchCenterView: React.FC = () => {
  const { materials } = useApp();

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedId, setSelectedId] = useState<number | null>(
    materials.length > 0 ? materials[0].id : null
  );

  const selectedMaterial = materials.find(
    material => material.id === selectedId
  );

  /*
   * Search real Supabase material records.
   */
  const filteredMaterials = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();

    if (!query) {
      return materials;
    }

    return materials.filter(material =>
      [
        material.company,
        material.material_number,
        material.description,
        material.specifications,
        material.category
      ]
        .filter(Boolean)
        .some(value =>
          String(value).toLowerCase().includes(query)
        )
    );
  }, [materials, searchQuery]);

  /*
   * Find other companies having records with similar text.
   * This is ONLY a basic database similarity view.
   * It does NOT claim to be AI matching.
   */
  const relatedMaterials = useMemo(() => {
    if (!selectedMaterial) {
      return [];
    }

    const selectedText = [
      selectedMaterial.description || '',
      selectedMaterial.specifications || '',
      selectedMaterial.category || ''
    ]
      .join(' ')
      .toLowerCase();

    const keywords = selectedText
      .split(/[\s,./()×x-]+/)
      .filter(word => word.length >= 4)
      .slice(0, 20);

    return materials
      .filter(material => material.id !== selectedMaterial.id)
      .filter(material => {
        const otherText = [
          material.description || '',
          material.specifications || '',
          material.category || ''
        ]
          .join(' ')
          .toLowerCase();

        const matchedWords = keywords.filter(word =>
          otherText.includes(word)
        ).length;

        return matchedWords >= 2;
      })
      .slice(0, 10);
  }, [materials, selectedMaterial]);

  const companies = ['BPCL', 'BHEL', 'HPCL', 'IOCL'];

  const companyCounts = companies.map(company => ({
    company,
    count: materials.filter(
      material =>
        material.company?.trim().toUpperCase() === company
    ).length
  }));

  if (materials.length === 0) {
    return (
      <div className="p-4 lg:p-6 max-w-[1600px] mx-auto">
        <div className="bg-white border border-slate-200 rounded-2xl p-12 text-center">
          <Database className="w-12 h-12 mx-auto text-slate-300 mb-4" />

          <h1 className="text-lg font-bold text-slate-900">
            No Material Data Available
          </h1>

          <p className="text-sm text-slate-500 mt-2">
            The AI Match Center requires material records from
            the Supabase database.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 lg:p-6 space-y-6 max-w-[1600px] mx-auto">

      {/* =====================================================
          HEADER
      ====================================================== */}

      <div className="bg-slate-950 text-white rounded-2xl border border-slate-800 p-6">

        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-5">

          <div>

            <div className="flex items-center gap-2 flex-wrap">

              <span className="bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 text-[10px] font-bold px-2.5 py-1 rounded-full uppercase tracking-wider font-mono">
                MATERIAL ANALYSIS
              </span>

              <span className="text-xs text-slate-400 font-mono">
                Live Database
              </span>

            </div>

            <h1 className="text-xl sm:text-2xl font-bold mt-2">
              Material Intelligence Center
            </h1>

            <p className="text-xs text-slate-300 mt-2 max-w-3xl leading-relaxed">
              Search and compare material records currently
              available in the national material database.
            </p>

          </div>

          <div className="flex items-center gap-2 bg-slate-900 border border-slate-800 rounded-xl px-4 py-3">

            <Database className="w-4 h-4 text-emerald-400" />

            <div>
              <div className="text-[10px] text-slate-400">
                DATABASE RECORDS
              </div>

              <div className="text-sm font-bold font-mono">
                {materials.length.toLocaleString()}
              </div>
            </div>

          </div>

        </div>

        {/* COMPANY SUMMARY */}

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-6">

          {companyCounts.map(item => (

            <div
              key={item.company}
              className="bg-slate-900 border border-slate-800 rounded-xl p-4"
            >

              <div className="text-[10px] text-slate-400 font-mono">
                {item.company}
              </div>

              <div className="text-xl font-bold font-mono mt-1 text-emerald-400">
                {item.count.toLocaleString()}
              </div>

              <div className="text-[10px] text-slate-500 mt-1">
                material records
              </div>

            </div>

          ))}

        </div>

      </div>


      {/* =====================================================
          SEARCH
      ====================================================== */}

      <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm">

        <div className="relative">

          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-3" />

          <input
            type="text"
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search material number, description, specification, company..."
            className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 text-sm text-slate-900 placeholder-slate-400 focus:outline-none focus:border-cyan-500"
          />

        </div>

        <div className="flex items-center justify-between mt-3">

          <span className="text-[10px] font-mono text-slate-400">
            {filteredMaterials.length.toLocaleString()} records found
          </span>

          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="text-xs text-slate-500 hover:text-slate-900 flex items-center gap-1"
            >
              <X className="w-3 h-3" />
              Clear
            </button>
          )}

        </div>

      </div>


      {/* =====================================================
          MAIN WORKSPACE
      ====================================================== */}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* MATERIAL LIST */}

        <div className="lg:col-span-4 bg-white rounded-2xl border border-slate-200 overflow-hidden">

          <div className="p-4 border-b border-slate-200">

            <div className="flex items-center justify-between">

              <h2 className="text-xs font-bold uppercase tracking-wider font-mono text-slate-800">
                Material Records
              </h2>

              <span className="text-[10px] font-mono text-slate-400">
                {filteredMaterials.length}
              </span>

            </div>

          </div>

          <div className="max-h-[700px] overflow-y-auto p-3 space-y-2">

            {filteredMaterials.map(material => {

              const selected =
                material.id === selectedId;

              return (
                <button
                  key={material.id}
                  onClick={() => setSelectedId(material.id)}
                  className={`w-full text-left p-3 rounded-xl border transition-all ${
                    selected
                      ? 'bg-slate-950 border-slate-950 text-white'
                      : 'bg-white border-slate-200 hover:border-cyan-400 hover:bg-slate-50'
                  }`}
                >

                  <div className="flex items-center justify-between gap-2">

                    <span
                      className={`text-[10px] font-mono font-bold px-2 py-1 rounded ${
                        selected
                          ? 'bg-cyan-400 text-slate-950'
                          : 'bg-slate-100 text-slate-700'
                      }`}
                    >
                      {material.company}
                    </span>

                    <span
                      className={`text-[10px] font-mono ${
                        selected
                          ? 'text-slate-400'
                          : 'text-slate-400'
                      }`}
                    >
                      #{material.id}
                    </span>

                  </div>

                  <div
                    className={`text-xs font-mono font-bold mt-2 ${
                      selected
                        ? 'text-cyan-300'
                        : 'text-slate-800'
                    }`}
                  >
                    {material.material_number ||
                      'Material number unavailable'}
                  </div>

                  <div
                    className={`text-xs mt-1 line-clamp-2 ${
                      selected
                        ? 'text-slate-300'
                        : 'text-slate-600'
                    }`}
                  >
                    {material.description ||
                      'Description unavailable'}
                  </div>

                </button>
              );

            })}

          </div>

        </div>


        {/* SELECTED MATERIAL */}

        <div className="lg:col-span-8 space-y-5">

          {selectedMaterial ? (
            <>
              {/* DETAILS */}

              <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">

                <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">

                  <div>

                    <div className="flex items-center gap-2">

                      <span className="bg-emerald-50 border border-emerald-200 text-emerald-700 text-[10px] font-bold px-2 py-1 rounded-full">
                        LIVE RECORD
                      </span>

                      <span className="text-xs text-slate-400 font-mono">
                        Database ID: {selectedMaterial.id}
                      </span>

                    </div>

                    <h2 className="text-lg font-bold text-slate-900 mt-3">
                      {selectedMaterial.description ||
                        'Material Description Unavailable'}
                    </h2>

                    <div className="text-sm font-mono font-bold text-cyan-700 mt-2">
                      {selectedMaterial.material_number ||
                        'Material Number Unavailable'}
                    </div>

                  </div>

                  <div className="bg-slate-100 rounded-xl px-4 py-3">

                    <div className="text-[10px] text-slate-400 uppercase">
                      Company
                    </div>

                    <div className="text-sm font-bold text-slate-900 mt-1">
                      {selectedMaterial.company}
                    </div>

                  </div>

                </div>


                {/* DETAILS GRID */}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">

                  <div className="bg-slate-50 rounded-xl border border-slate-100 p-4">

                    <div className="flex items-center gap-2 text-xs font-bold text-slate-600">
                      <Tag className="w-4 h-4" />
                      Category
                    </div>

                    <div className="text-sm font-semibold text-slate-900 mt-2">
                      {selectedMaterial.category ||
                        'Not available'}
                    </div>

                  </div>


                  <div className="bg-slate-50 rounded-xl border border-slate-100 p-4">

                    <div className="flex items-center gap-2 text-xs font-bold text-slate-600">
                      <Building2 className="w-4 h-4" />
                      Source Company
                    </div>

                    <div className="text-sm font-semibold text-slate-900 mt-2">
                      {selectedMaterial.company ||
                        'Not available'}
                    </div>

                  </div>

                </div>


                {/* SPECIFICATIONS */}

                <div className="mt-4">

                  <div className="flex items-center gap-2 text-xs font-bold text-slate-700 uppercase tracking-wider font-mono mb-2">

                    <FileText className="w-4 h-4" />

                    Specifications

                  </div>

                  <div className="bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm text-slate-700 leading-relaxed whitespace-pre-wrap">
                    {selectedMaterial.specifications ||
                      'No specifications available.'}
                  </div>

                </div>

              </div>


              {/* ANALYSIS STATUS */}

              <div className="bg-slate-950 text-white rounded-2xl border border-slate-800 p-6">

                <div className="flex items-center gap-2">

                  <Sparkles className="w-5 h-5 text-cyan-400" />

                  <h3 className="text-sm font-bold">
                    Intelligence Analysis
                  </h3>

                </div>

                <div className="mt-4 p-4 bg-slate-900 rounded-xl border border-slate-800">

                  <div className="flex items-start gap-3">

                    <CheckCircle2 className="w-5 h-5 text-emerald-400 mt-0.5 shrink-0" />

                    <div>

                      <div className="text-sm font-bold">
                        Material record available
                      </div>

                      <p className="text-xs text-slate-400 mt-1 leading-relaxed">
                        This record is present in the Supabase
                        material database and can be used as input
                        for future AI standardization and matching.
                      </p>

                    </div>

                  </div>

                </div>

                <div className="mt-3 p-4 bg-amber-500/5 rounded-xl border border-amber-500/20">

                  <div className="flex items-start gap-3">

                    <AlertCircle className="w-5 h-5 text-amber-400 mt-0.5 shrink-0" />

                    <div>

                      <div className="text-sm font-bold text-amber-300">
                        AI matching not yet available
                      </div>

                      <p className="text-xs text-slate-400 mt-1 leading-relaxed">
                        No real AI match score has been calculated
                        for this record yet. The system will not
                        display an invented confidence percentage.
                      </p>

                    </div>

                  </div>

                </div>

              </div>


              {/* RELATED RECORDS */}

              <div className="bg-white rounded-2xl border border-slate-200 p-6">

                <div className="flex items-center justify-between">

                  <div>

                    <h3 className="text-sm font-bold text-slate-900">
                      Potentially Related Records
                    </h3>

                    <p className="text-xs text-slate-500 mt-1">
                      Basic text similarity from current database records
                    </p>

                  </div>

                  <span className="text-xs font-mono font-bold bg-slate-100 text-slate-700 px-3 py-1 rounded-lg">
                    {relatedMaterials.length}
                  </span>

                </div>


                {relatedMaterials.length === 0 ? (

                  <div className="mt-5 p-6 bg-slate-50 rounded-xl border border-slate-100 text-center">

                    <AlertCircle className="w-8 h-8 mx-auto text-slate-300" />

                    <p className="text-xs text-slate-500 mt-2">
                      No related records identified from the
                      currently available data.
                    </p>

                  </div>

                ) : (

                  <div className="mt-4 space-y-2">

                    {relatedMaterials.map(material => (

                      <button
                        key={material.id}
                        onClick={() =>
                          setSelectedId(material.id)
                        }
                        className="w-full text-left flex items-center justify-between gap-4 p-4 rounded-xl border border-slate-200 hover:border-cyan-400 hover:bg-slate-50 transition-colors"
                      >

                        <div className="min-w-0">

                          <div className="flex items-center gap-2">

                            <span className="text-[10px] font-bold font-mono bg-slate-100 text-slate-700 px-2 py-1 rounded">
                              {material.company}
                            </span>

                            <span className="text-[10px] text-slate-400 font-mono">
                              {material.material_number || 'No code'}
                            </span>

                          </div>

                          <div className="text-xs font-semibold text-slate-900 mt-2">
                            {material.description ||
                              'No description'}
                          </div>

                        </div>

                        <ArrowRight className="w-4 h-4 text-slate-400 shrink-0" />

                      </button>

                    ))}

                  </div>

                )}

              </div>

            </>
          ) : (

            <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">

              <Database className="w-10 h-10 mx-auto text-slate-300" />

              <p className="text-sm text-slate-500 mt-3">
                Select a material record.
              </p>

            </div>

          )}

        </div>

      </div>

    </div>
  );
};